# Describe Azure compute and networking services. Per test 6, drill-only 7.
ITEMS = [
    # ---- Test 1 ----
    S(1, 1, "Virtual Machine Scale Sets",
      "A company needs a group of identical, load-balanced virtual machines that automatically increase in number as demand grows. Which service should it use?",
      "Azure Virtual Machine Scale Sets",
      ["Azure availability sets", "Azure Virtual Desktop session hosts", "Azure Dedicated Host"],
      "Virtual Machine Scale Sets create and manage a group of identical, load-balanced VMs and can add or remove instances automatically with demand or on a schedule. Availability sets spread VMs across hardware for resilience but do not scale the number of VMs."),
    S(1, 2, "Availability sets",
      "What do availability sets provide for virtual machines?",
      "Spreading VMs across fault and update domains",
      ["Automatic scaling based on CPU usage", "Placing each VM in its own separate Azure region", "Desktop sessions for remote workers"],
      "An availability set spreads VMs across fault domains (separate power and network hardware) and update domains (groups that are rebooted at different times for maintenance), so one failure or update does not stop them all. It does not scale the number of VMs or span regions."),
    S(1, 1, "Azure Virtual Desktop",
      "A company wants employees to reach a Windows desktop and their apps, hosted in Azure, from any device. Which service fits?",
      "Azure Virtual Desktop",
      ["Azure Virtual Machine Scale Sets", "Azure App Service", "Azure Container Instances"],
      "Azure Virtual Desktop is desktop and app virtualization in the cloud: users connect to a full Windows experience from almost any device, and data stays in Azure rather than on the device. Scale Sets run groups of server VMs, not user desktops."),
    S(1, 2, "ExpressRoute",
      "A company needs a private connection from its datacenter to Azure that does not travel over the public internet. What should it use?",
      "Azure ExpressRoute",
      ["A site-to-site VPN through Azure VPN Gateway", "Virtual network peering", "An Azure DNS private zone"],
      "ExpressRoute extends an on-premises network into the Microsoft cloud over a private connection through a connectivity provider, so traffic does not cross the public internet. A site-to-site VPN is encrypted, but it does travel over the internet."),
    MT(1, 2, "Compute types",
       "Match each requirement to the compute type that fits it best.",
       ["Virtual machines", "Containers", "Functions"],
       [("Run code in response to an event and pay per execution", 2),
        ("Full control of the operating system for legacy software", 0),
        ("Package an app with its dependencies to run on a shared OS kernel", 1),
        ("Install a custom agent on each server's operating system", 0)],
       "Virtual machines give full control of the operating system, so they suit legacy software and OS-level agents. Containers package an app with its dependencies and share the host kernel, so they are light and start fast. Functions run event-driven code and can bill per execution."),
    M(1, 2, "Resources for a VM",
      "An administrator creates an Azure virtual machine. Which two resources does the VM need? (Choose two.)",
      ["A virtual network", "A managed disk for the operating system"],
      ["An Azure Functions app", "A management group", "A Log Analytics workspace for monitoring data"],
      "A VM needs a size, storage disks (at least an OS disk) and networking, which means a virtual network and a network interface, plus a public IP address if it must be reachable from the internet. A Log Analytics workspace is optional monitoring, and Functions and management groups are unrelated."),

    # ---- Test 2 ----
    S(2, 1, "Virtual network peering",
      "Two Azure virtual networks need to communicate privately with each other. What should you configure?",
      "Virtual network peering",
      ["Azure ExpressRoute", "A public endpoint on each network", "An Azure DNS zone"],
      "Peering connects two virtual networks so that traffic flows between them privately over the Microsoft backbone, even across regions. ExpressRoute connects on-premises networks to Azure, not one Azure virtual network to another."),
    S(2, 1, "VPN Gateway",
      "A branch office needs an encrypted connection to an Azure virtual network over the internet. Which service should it use?",
      "Azure VPN Gateway",
      ["Azure ExpressRoute", "Virtual network peering", "Azure DNS"],
      "Azure VPN Gateway sends encrypted traffic between an Azure virtual network and an on-premises location over the public internet, in a site-to-site connection. ExpressRoute is a private connection that does not use the internet, and needs a connectivity provider."),
    S(2, 2, "Private endpoints",
      "What does a private endpoint do?",
      "Brings an Azure service into your VNet on a private IP",
      ["Exposes a virtual machine to the internet on a public IP",
       "Links an on-premises site over a dedicated private circuit",
       "Translates domain names into IP addresses for a zone"],
      "A private endpoint gives a service such as a storage account or SQL database a private IP address in your virtual network, so traffic to it stays on the Microsoft network and the public endpoint can be turned off. A dedicated private circuit from on premises is ExpressRoute."),
    S(2, 1, "Azure DNS",
      "Which service hosts DNS domains in Azure, so that name resolution runs on Microsoft's infrastructure?",
      "Azure DNS",
      ["Azure VPN Gateway", "Virtual network peering", "Azure ExpressRoute"],
      "Azure DNS hosts DNS domains and provides name resolution on Microsoft Azure infrastructure, managed with the same credentials, APIs, tools and billing as other Azure services. The other options connect networks; they do not resolve names."),
    S(2, 2, "Container hosting",
      "A team wants to run a container quickly without managing any virtual machines or a container orchestrator. Which service is simplest?",
      "Azure Container Instances",
      ["Azure Kubernetes Service", "Azure Virtual Machine Scale Sets", "Azure Virtual Desktop"],
      "Azure Container Instances is the fastest and simplest way to run a container in Azure, a PaaS offering with no VMs or orchestrator to manage. Azure Kubernetes Service orchestrates many containers, which is more than this team needs."),
    YN(2, 2, "Virtual networking",
       "For each statement about Azure virtual networking, select Yes if it is true or No if it is false.",
       [("Subnets divide a virtual network's address space into segments.", True),
        ("Resources in different subnets of the same virtual network cannot communicate by default.", False),
        ("Traffic between peered virtual networks travels over the Microsoft backbone network.", True),
        ("ExpressRoute connections travel over the public internet.", False)],
       "Subnets split a virtual network's address space, and by default resources in any subnet of the same virtual network can reach each other. Peered traffic stays on the Microsoft backbone, and ExpressRoute is a private connection that does not use the public internet."),

    # ---- Drill only ----
    S(0, 1, "App hosting",
      "A team wants to host a web app and an API with built-in autoscaling and deployment slots, without managing virtual machines. Which option fits?",
      "Azure App Service",
      ["Azure Virtual Machines", "Azure Virtual Desktop", "Azure Dedicated Host"],
      "Azure App Service is a fully managed PaaS for web apps, APIs and mobile back ends, with autoscaling, deployment slots and CI/CD built in. Virtual Machines would leave the team managing the operating system and web server."),
    S(0, 2, "Fault domains",
      "In an availability set, what does a fault domain represent?",
      "A group of VMs that share power and network hardware",
      ["A group of VMs restarted together for planned maintenance", "A separate Azure region used for failover", "A set of VMs all created from one image"],
      "A fault domain is a group of VMs that share a common power source and network switch, like a rack, so a hardware failure affects only that domain. A group restarted together for planned maintenance is an update domain."),
    S(0, 2, "Functions and VMs",
      "Which is a key difference between Azure Functions and Azure Virtual Machines?",
      "Functions scale automatically and can bill per execution",
      ["Functions give full control of the operating system", "Virtual machines bill only when code is triggered", "Virtual machines need no operating system patching by the customer"],
      "Functions is serverless: it runs code when an event fires, scales automatically and can charge only for execution time. A virtual machine runs and bills continuously while allocated, and the customer manages and patches its operating system."),
    S(0, 1, "Public endpoints",
      "A storage account can be reached from the internet at its public URL. What kind of endpoint is this?",
      "A public endpoint",
      ["A private endpoint", "A peering endpoint", "A gateway subnet"],
      "A public endpoint is reachable from the internet at a public address. A private endpoint gives the service an IP address inside your virtual network so it can be reached privately instead."),
    M(0, 2, "ExpressRoute benefits",
      "Which two are benefits of Azure ExpressRoute compared with a VPN over the internet? (Choose two.)",
      ["Traffic does not cross the public internet", "More consistent latency and higher reliability"],
      ["It works without any virtual network gateway at all", "It is free at every bandwidth level", "It removes the need for a virtual network"],
      "Because ExpressRoute uses a private connection, it offers more reliability, faster speeds, consistent latencies and higher security than typical internet connections. It is a paid service, and it still connects to Azure virtual networks through a gateway."),
    MT(0, 2, "Networking services",
       "Match each need to the Azure networking service that meets it.",
       ["VPN Gateway", "ExpressRoute", "VNet peering", "Azure DNS"],
       [("Connect two Azure virtual networks privately", 2),
        ("Encrypted tunnel over the internet to a branch office", 0),
        ("Dedicated private circuit from a company datacenter", 1),
        ("Resolve names for a domain hosted in Azure", 3)],
       "Peering links virtual networks inside Azure. VPN Gateway builds encrypted tunnels across the internet, while ExpressRoute is a private circuit through a connectivity provider. Azure DNS hosts domains and resolves their names."),
    S(0, 3, "Containers and VMs",
      "Why do containers usually start faster than virtual machines?",
      "They share the host operating system instead of booting their own",
      ["They each run on their own separate, dedicated physical server host", "They keep a full guest operating system running when idle", "They are always stored on premium SSD managed disks"],
      "A container packages an app and its dependencies but shares the host's operating system kernel, so there is no guest operating system to boot. A virtual machine virtualizes hardware and must start a full operating system of its own."),
]
